sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
layout(color) uniform half4 color;
uniform float opacity;
uniform float blur;
uniform float x;
uniform float y;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float sa = float(blurred.eval(coord - float2(x, y)).a) * clamp(opacity, 0.0, 1.0) * float(color.a);
    half4 s = half4(half3(color.rgb) * half(sa), half(sa));
    return src + s * (1.0 - src.a);
}
